/**
 * Shared deserializer AST for filters, sorts, and the catalog references
 * they carry. Lifted out of `src/automations/deserializer/ast.ts` so other
 * tool surfaces (agent search tools, future skill/flow tools) can use
 * the same printer infrastructure without forking the type definitions.
 *
 * ## One catalog-ref vocabulary, two containers
 *
 * The standalone catalog-ref nodes below (`AppRefAst`, `FieldRefAst`,
 * `AgentRefAst`, `AutomationRefAst`, `SearchTableRefAst`,
 * `ApprovalChainRefAst`) are the single definition of "a reference into
 * the catalog." They show up in two positions:
 *
 *   - **bare**, in a fixed builder slot that can only hold one kind of
 *     ref — a tool's `aspect:`, an approval chain's `lockedFields:`, a
 *     search table's `attributeFields:`. Every entity deserializer's
 *     `ast.ts` imports these directly.
 *   - **as members of `RefExpr`**, the union for a *polymorphic* slot — a
 *     filter / sort / task argument, where the value could equally be a
 *     literal, a template, or a task/trigger reference.
 *
 * `RefExpr` therefore *composes* these nodes rather than redefining them:
 * a field ref is `{ kind: "field", ... }` whether it stands alone or sits
 * inside a filter. The value/flow kinds (`literal`, `template`, `taskRef`,
 * …) only exist inside `RefExpr` because they only ever appear in a
 * polymorphic slot. Each node's `kind` names the catalog bag it points at
 * (`"field"`, `"app"`, …) — distinct from the `MissingDataCollector`
 * category strings (`"fieldRef"`, `"valueRef"`, …), which are an unrelated
 * enum despite the similar spelling.
 *
 * The shared printer handles every kind; per-consumer normalize stages
 * only emit the kinds their wire shape actually carries (agent search
 * filters, for instance, only produce `literal`, `field`, `app`, and
 * `unresolved`).
 */
// ---------------------------------------------------------------------------
// Type guards — runtime shape checks for the AST nodes above
// ---------------------------------------------------------------------------
/**
 * Runtime predicate matching the closed `RefExpr` discriminant set.
 * Used by shared printers and per-consumer printers to identify reference
 * nodes without conflating them with canonical `type`-discriminated values.
 * printers when dispatching generic task-arg values.
 */
export function isRefExpr(value) {
    if (!value || typeof value !== "object")
        return false;
    const kind = value.kind;
    return (kind === "literal" ||
        kind === "taskRef" ||
        kind === "triggerRef" ||
        kind === "forEachRef" ||
        kind === "forEachItemRef" ||
        kind === "variableParamRef" ||
        kind === "template" ||
        kind === "field" ||
        kind === "app" ||
        kind === "agent" ||
        kind === "automation" ||
        kind === "documentModel" ||
        kind === "documentModelField" ||
        kind === "approvalChain" ||
        kind === "datamine" ||
        kind === "table" ||
        kind === "tableColumn" ||
        kind === "searchTable" ||
        kind === "connector" ||
        kind === "cloudLink" ||
        kind === "procedure" ||
        kind === "phoneService" ||
        kind === "user" ||
        kind === "unresolved");
}
